(function(root){'use strict';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const G=()=>root.THLaundryGuide,S=()=>root.THLaundryScenarios,U=()=>root.THLaundryUI;
const time=v=>v?new Date(v).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'}):'';
function summary(o,m,accounting={}){const ss=G().steps(o,m.role),done=ss.filter(s=>s.state==='done').length,total=ss.filter(s=>s.state!=='skip').length,closed=ss.at(-1).state==='done';return `<section class="guide-overview"><div><span class="eyebrow">URUTAN KERJA · SOP v0.4</span><h2>${closed?(o.linkedThl?'Barang ditautkan · buka pesanan pelanggan':'Alur barang & dana terselesaikan'):'Selesaikan satu langkah berikutnya'}</h2><p>${done} dari ${total} langkah selesai. Centang mengikuti bukti dan tindakan yang tersimpan.</p><progress max="${total}" value="${done}" aria-label="Langkah order selesai">${done}/${total}</progress></div><div class="guide-report"><strong>Pesanan sudah masuk jurnal usaha</strong><span>${E(accounting.status||'Status pembukuan sedang diperiksa')}</span><small>${accounting.posted||0} dari ${accounting.expected||0} kejadian keuangan dibukukan.</small><a class="button" href="/?view=finance&order=${encodeURIComponent(o.id)}">Periksa laporan order</a>${o.linkedThl?`<a href="/laundry-desk?order=${encodeURIComponent(o.linkedThl)}">Buka pesanan ${E(o.linkedThl)}</a>`:''}</div></section>`;}
function checklist(o,m,actions){const steps=G().steps(o,m.role),next=steps.find(s=>s.state==='pending'&&actions.includes(s.action));return `<section class="card guide-checklist"><div class="row spread"><h2>Checklist penyelesaian</h2><label>Tampilkan<select data-guide-role><option value="all">Semua peran</option><option value="mine">Tugas ${E(m.role)}</option></select></label></div><p class="muted">Ikuti nomor urut. Pembayaran dapat dilengkapi sebelum serah terima; langkah yang menunggu orang lain tetap terlihat.</p><ol class="guide-steps">${steps.map(s=>`<li data-guide-step data-mine="${s.role.includes(m.role)||m.role==='Owner'&&s.role.includes('Operator')}" class="guide-step ${s.state} ${next?.id===s.id?'current':''}"><span class="step-number" aria-label="${s.state==='done'?'Selesai':s.state==='skip'?'Tidak diperlukan':'Langkah '+s.number}">${s.state==='done'?'✓':s.state==='skip'?'–':s.number}</span><div><div class="row spread"><strong>${E(s.number+'. '+s.title)}</strong><span class="role-chip">${E(s.role)}</span></div><p>${E(s.text)}</p>${s.state==='done'?`<small class="success-text">Selesai${s.actor?' · '+E(s.actor):''}${s.at?' · '+E(time(s.at)):''}</small>`:s.state==='skip'?'<small>Tidak diperlukan pada jalur ini.</small>':actions.includes(s.action)?`<button class="${next?.id===s.id?'primary':''}" data-guide-action="${E(s.action)}">${next?.id===s.id?'Kerjakan berikutnya':'Buka langkah ini'}</button>`:s.action==='link-int'&&m.role==='Owner'?'<button class="primary" data-guide-link>Pastikan pemilik & buat pesanan</button>':s.id==='identify'&&o.kind==='THL'?'<small>Menunggu konfirmasi pelanggan / Owner. Timbangan boleh diisi bila barang sudah diterima.</small>':'<small>Menunggu prasyarat atau petugas yang berwenang.</small>'}</div></li>`).join('')}</ol><p class="guide-footnote">Centang tidak dapat dipaksakan. Pemeriksaan panduan dicatat terpisah dan tidak mengganti bukti, persetujuan, atau pencocokan dana.</p></section>`;}
function scenarioCard(s,o,m,active){const reviews=o?.sopReviews||[],key=o?G().reviewKey(o):'',state=r=>r.signature===key?'Sudah diperiksa':'Periksa ulang · order berubah';return `<details class="scenario-card" data-scenario="${s.id}" data-related="${active}"><summary><span class="scenario-number">${s.id}</span><span>${E(s.title)}</span>${active?'<span class="role-chip">Terkait order</span>':''}</summary>${s.limit?`<p class="alert warning">${E(s.limit)}</p>`:''}<div class="scenario-roles">${[['operator','Operator'],['owner','Owner'],...(m?.role==='Finance'?[['owner','Finance']]:[])].map(([keyName,role])=>{const r=reviews.find(x=>x.scenarioId===s.id&&x.role===role);return `<section><h3>${role}</h3><ol>${s[keyName].map(step=>`<li>${E(step)}</li>`).join('')}</ol>${r?`<p class="review-receipt ${r.signature===key?'success':'warning'}"><strong>${E(state(r))}</strong><br>${E(r.name)} · ${E(time(r.at))}<br>${E(r.note)}</p>`:'<p class="muted">Belum ada catatan pemeriksaan peran ini.</p>'}</section>`;}).join('')}</div><p><strong>Bukti yang diperiksa</strong></p><ul>${s.evidence.map(e=>`<li>${E(e)}</li>`).join('')}</ul><div class="scenario-closure"><strong>Kondisi penyelesaian</strong><p>${E(s.closure)}</p></div>${o?`<button data-sop-review="${s.id}">Catat pemeriksaan ${E(m.role)}</button>`:''}</details>`;}
function scenarios(o,m){const related=G().related(o);return `<section class="card scenario-library"><span class="eyebrow">PANDUAN JIKA ADA KONDISI KHUSUS</span><h2>28 skenario · dari masuk sampai selesai</h2><p class="muted">Buka skenario yang sesuai. “Sudah diperiksa” adalah catatan petugas, bukan tanda order otomatis selesai.</p><div class="scenario-controls"><label>Cari kondisi<input data-scenario-search type="search" placeholder="Batal, label, refund, setoran…"></label><label>Tampilkan<select data-scenario-scope><option value="related">Terkait order ini</option><option value="all">Semua 28 skenario</option></select></label></div><p data-scenario-empty hidden>Tidak ada skenario yang cocok. Tampilkan semua atau ganti pencarian.</p>${S().map(s=>scenarioCard(s,o,m,related.includes(s.id))).join('')}</section>`;}
function filter(scope=document){const q=(scope.querySelector('[data-scenario-search]')?.value||'').toLowerCase(),mode=scope.querySelector('[data-scenario-scope]')?.value||'all';let count=0;scope.querySelectorAll('[data-scenario]').forEach(el=>{el.hidden=(mode==='related'&&el.dataset.related!=='true')||!el.textContent.toLowerCase().includes(q);if(!el.hidden)count++;});const empty=scope.querySelector('[data-scenario-empty]');if(empty)empty.hidden=count>0;}
function bind(o,m,handlers){document.querySelectorAll('[data-guide-action]').forEach(b=>b.onclick=()=>handlers.action(b.dataset.guideAction));document.querySelector('[data-guide-link]')?.addEventListener('click',handlers.link);document.querySelectorAll('[data-sop-review]').forEach(b=>b.onclick=()=>handlers.review(b.dataset.sopReview));document.querySelector('[data-guide-role]')?.addEventListener('change',e=>document.querySelectorAll('[data-guide-step]').forEach(row=>row.hidden=e.target.value==='mine'&&row.dataset.mine!=='true'));document.querySelector('[data-scenario-search]')?.addEventListener('input',()=>filter());document.querySelector('[data-scenario-scope]')?.addEventListener('change',()=>filter());filter();}
function library(){const modal=document.querySelector('#modal');modal.innerHTML=`<div class="row spread"><h2>Panduan 28 skenario SOP v0.4</h2><button data-library-close>Tutup</button></div><p>Buka order untuk melihat checklist sesuai kondisi dan mencatat pemeriksaan atas nama akun Anda.</p><label>Cari kondisi<input type="search" data-scenario-search placeholder="Cari nomor atau kondisi…"></label>${S().map(s=>scenarioCard(s,null,null,false)).join('')}`;modal.showModal();modal.querySelector('[data-library-close]').onclick=()=>modal.close();modal.querySelector('[data-scenario-search]').oninput=()=>filter(modal);}
root.THLaundryGuideUI={summary,checklist,scenarios,bind,library};
})(window);
